#include <iostream>
using namespace std;

int main() {
    // Lettura dati di input
    int uno, due, tre;
    int maggiore;

    cout << "Inserisci tre numeri: " << endl;
    cin >> uno >> due >> tre;

    // Logica del programma
    if (uno > due) {
        if (uno > tre)
            maggiore = uno;
        else
            maggiore = tre;
    } else {
        if (due > tre)
            maggiore = due;
        else
            maggiore = tre;
    }

    // Scrittura dei dati di output
    cout << "Il numero maggiore e': " << maggiore << endl;

    system("pause");
}
